import{_ as t,o as a,c as s,a2 as o}from"./chunks/framework.DT_qyuxR.js";const m=JSON.parse('{"title":"Le Combat","description":"","frontmatter":{},"headers":[],"relativePath":"gitbook/regles/05-combat.md","filePath":"gitbook/regles/05-combat.md"}'),r={name:"gitbook/regles/05-combat.md"};function l(i,e,n,u,d,c){return a(),s("div",null,[...e[0]||(e[0]=[o('<h1 id="le-combat" tabindex="-1">Le Combat <a class="header-anchor" href="#le-combat" aria-label="Permalink to &quot;Le Combat&quot;">​</a></h1><h2 id="les-duels" tabindex="-1">Les Duels <a class="header-anchor" href="#les-duels" aria-label="Permalink to &quot;Les Duels&quot;">​</a></h2><p>Le combat central de Carnival of the Deads est le <strong>Duel</strong> : un affrontement direct entre deux joueurs.</p><h3 id="declencher-un-duel" tabindex="-1">Déclencher un Duel <a class="header-anchor" href="#declencher-un-duel" aria-label="Permalink to &quot;Déclencher un Duel&quot;">​</a></h3><ol><li><strong>Choisir une cible</strong> : vous devez être dans le <strong>même salon vocal</strong> que votre cible.</li><li><strong>Envoyer le défi</strong> : via votre panneau joueur (en MP), sélectionnez l&#39;action &quot;Défier en Duel&quot;.</li><li><strong>Attendre la réponse</strong> : le joueur ciblé reçoit une demande d&#39;acceptation.</li><li><strong>Accepter ou refuser</strong> : <ul><li><strong>Accepté</strong> → le Duel est enregistré et résolu à la fin de la phase.</li><li><strong>Refusé</strong> → le défi est annulé, aucune conséquence.</li></ul></li></ol><h3 id="resolution-automatique" tabindex="-1">Résolution automatique <a class="header-anchor" href="#resolution-automatique" aria-label="Permalink to &quot;Résolution automatique&quot;">​</a></h3><p>Tous les Duels acceptés sont résolus <strong>automatiquement</strong> à la fin de la phase de Duels :</p><ol><li>Chaque duo de duellistes s&#39;attaque mutuellement avec son <strong>Attaque de Combat</strong>.</li><li>Les dégâts sont appliqués <strong>simultanément</strong>.</li><li>Si un masque se brise pendant un Duel, l&#39;identité est révélée, mais le Duel continue (l&#39;autre joueur attaque quand même).</li></ol><blockquote><p><strong>Important</strong> : même si votre adversaire tombe K.O. avant vous, votre attaque est quand même appliquée. Les dégâts sont symétriques.</p></blockquote><h3 id="duels-multiples" tabindex="-1">Duels multiples <a class="header-anchor" href="#duels-multiples" aria-label="Permalink to &quot;Duels multiples&quot;">​</a></h3><p>Il est possible de participer à <strong>plusieurs Duels</strong> lors de la même phase. Le bot gère automatiquement les Duels multiples.</p><h2 id="l-attaque-de-combat" tabindex="-1">L&#39;Attaque de Combat <a class="header-anchor" href="#l-attaque-de-combat" aria-label="Permalink to &quot;L&#39;Attaque de Combat&quot;">​</a></h2><p>Chaque masque possède une <strong>Attaque de Combat</strong> unique avec des dégâts fixes.</p><h3 id="exemples" tabindex="-1">Exemples <a class="header-anchor" href="#exemples" aria-label="Permalink to &quot;Exemples&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Masque</th><th>Attaque</th><th>Dégâts</th><th>Effet supplémentaire</th></tr></thead><tbody><tr><td>Épine</td><td>Aiguillon</td><td>2</td><td>Ronces (renvoie des dégâts)</td></tr><tr><td>Empathique</td><td>Gros Câlin</td><td>1</td><td>Soin + Empathie</td></tr><tr><td>Sacrifice</td><td>Pointe</td><td>6</td><td>-3 PV à l&#39;attaquant</td></tr><tr><td>Maestro</td><td>Moderato</td><td>2</td><td>Augmente les dégâts subis par la cible</td></tr><tr><td>Rocher</td><td>Frappe de Pierre</td><td>3</td><td>-50% dégâts reçus (passif)</td></tr></tbody></table><h3 id="degats-fixes" tabindex="-1">Dégâts fixes <a class="header-anchor" href="#degats-fixes" aria-label="Permalink to &quot;Dégâts fixes&quot;">​</a></h3><p>Les dégâts de combat sont <strong>fixes</strong> : ils ne sont pas modifiés par des effets extérieurs. Il n&#39;y a pas de statuts (Brûlure, Poison, etc.) dans Carnival of the Deads.</p><blockquote><p><strong>Exception</strong> : le passif de l&#39;Effroi (Terreur) réduit les dégâts de l&#39;adversaire de 1 pendant le Duel. C&#39;est un bonus de Duel, pas un statut.</p></blockquote><h2 id="capacites-de-combat-speciales" tabindex="-1">Capacités de combat spéciales <a class="header-anchor" href="#capacites-de-combat-speciales" aria-label="Permalink to &quot;Capacités de combat spéciales&quot;">​</a></h2><p>Certains masques ont des effets spéciaux déclenchés pendant le combat :</p><h3 id="maestro-—-moderato" tabindex="-1">Maestro — Moderato <a class="header-anchor" href="#maestro-—-moderato" aria-label="Permalink to &quot;Maestro — Moderato&quot;">​</a></h3><p>Inflige 2 dégâts + ajoute un modifier : les prochains dégâts subis par la cible sont augmentés de 1. Ce modifier s&#39;applique à la <strong>prochaine instance de dégâts</strong> (combat ou autre).</p><h3 id="empathique-—-gros-calin" tabindex="-1">Empathique — Gros Câlin <a class="header-anchor" href="#empathique-—-gros-calin" aria-label="Permalink to &quot;Empathique — Gros Câlin&quot;">​</a></h3><p>Inflige 1 dégâts + soigne. Un masque de support avec sustain.</p><h3 id="sacrifice-—-pointe" tabindex="-1">Sacrifice — Pointe <a class="header-anchor" href="#sacrifice-—-pointe" aria-label="Permalink to &quot;Sacrifice — Pointe&quot;">​</a></h3><p>Inflige 6 dégâts (le plus puissant du jeu) mais l&#39;attaquant subit 3 dégâts. Un pari risqué.</p><h3 id="foyer-—-gant-d-amour-avec-lien-familial" tabindex="-1">Foyer — Gant d&#39;amour (avec Lien Familial) <a class="header-anchor" href="#foyer-—-gant-d-amour-avec-lien-familial" aria-label="Permalink to &quot;Foyer — Gant d&#39;amour (avec Lien Familial)&quot;">​</a></h3><p>Si l&#39;Enfant du Foyer est encore en vie, les dégâts sont infligés <strong>deux fois</strong>. C&#39;est le passif le plus dévastateur du jeu.</p><h2 id="regles-importantes" tabindex="-1">Règles importantes <a class="header-anchor" href="#regles-importantes" aria-label="Permalink to &quot;Règles importantes&quot;">​</a></h2><h3 id="pas-de-fuite" tabindex="-1">Pas de fuite <a class="header-anchor" href="#pas-de-fuite" aria-label="Permalink to &quot;Pas de fuite&quot;">​</a></h3><p>Un Duel ne peut pas être annulé une fois accepté. Seul le refus du défi l&#39;annule.</p><h3 id="pas-de-treve" tabindex="-1">Pas de trêve <a class="header-anchor" href="#pas-de-treve" aria-label="Permalink to &quot;Pas de trêve&quot;">​</a></h3><p>Un Duel peut être déclenché entre n&#39;importe quels joueurs du même salon, même s&#39;ils sont alliés (Vivants contre Vivants, ou Revenants contre Revenants).</p><h3 id="k-o-pendant-un-duel" tabindex="-1">K.O. pendant un Duel <a class="header-anchor" href="#k-o-pendant-un-duel" aria-label="Permalink to &quot;K.O. pendant un Duel&quot;">​</a></h3><p>Si un masque se brise pendant un Duel, l&#39;identité est révélée mais le Duel continue. L&#39;autre joueur attaque quand même.</p><h3 id="pas-de-mort-multiple" tabindex="-1">Pas de mort multiple <a class="header-anchor" href="#pas-de-mort-multiple" aria-label="Permalink to &quot;Pas de mort multiple&quot;">​</a></h3><p>Un joueur ne peut pas mourir deux fois. Si un masque est déjà brisé, il ne peut plus être ciblé.</p>',37)])])}const h=t(r,[["render",l]]);export{m as __pageData,h as default};
